/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  var D = {"names": ["System Code", "Insulation Spec", "Circuit Ref", "Maint. Zone"], "old": ["Sys Cd", null, null, null], "HV": 412, "LV": 874};
  phases([[0,22],[22,36],[36,54],[54,80]]);
  v.dO = lin([[0,0],[3,1]]) * out; v.dT = 'translateY(' + lin([[0,14],[3,0]]).toFixed(1) + 'px)';
  for (var i = 0; i < 4; i++) {
    var nm = D.names[i], old = D.old[i];
    if (old) {
      // existing parameter, renamed during phase 2
      var rs = 23;
      if (p < rs) { v['nm'+i] = old; v['cur'+i] = 0; }
      else { var n = Math.min(nm.length, Math.floor((p - rs) / 3 * nm.length)); v['nm'+i] = n > 0 ? nm.slice(0, n) : old; v['cur'+i] = (p < rs + 3) ? 1 : 0; }
      v['rest'+i] = 1; v['chip'+i] = (p >= rs + 3 && p < 97) ? out : 0;
    } else {
      var s = 4 + (i - 1) * 6, n = Math.max(0, Math.min(nm.length, Math.floor((p - s) / 4 * nm.length)));
      v['nm'+i] = nm.slice(0, n); v['cur'+i] = (p >= s && p < s + 4.5) ? 1 : 0;
      v['rest'+i] = p >= s + 4 ? 1 : 0; v['chip'+i] = (p >= 28 + i * 1.5 && p < 97) ? out : 0;
    }
  }
  v.hO = lin([[34,0],[37,1]]) * out; v.lO = lin([[52,0],[55,1]]) * out;
  v.hv = Math.round(D.HV * lin([[38,0],[52,1]])).toLocaleString('en-US');
  for (var i = 0; i < 4; i++) v['sg'+i] = (p >= 56 + i * 5 && p < 97) ? out : 0;
  v.lv = Math.round(D.LV * lin([[61,0],[70,1]])).toLocaleString('en-US');
  v.fin = (p >= 77 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
